            Effect.gen(function* () {
              yield* stopShell(st.shell)
              yield* idleIfCurrent()
            }),
            { _tag: "Idle" } as const,
          ] as const
        case "ShellThenRun":
          return [
            Effect.gen(function* () {
              yield* Deferred.fail(st.run.done, new Cancelled()).pipe(Effect.asVoid)
              yield* stopShell(st.shell)
              yield* idleIfCurrent()
            }),
            { _tag: "Idle" } as const,
          ] as const
