    write(path.join(folder, 'DEGRADED.md'), `DEGRADED ${now()}\n无成功 Evaluator；宿主必须自评并在 SUMMARY.md 写出证据与局限。\n`);
  } else fs.rmSync(path.join(folder, 'DEGRADED.md'), { force: true });
