import { tool, type Plugin } from "@opencode-ai/plugin"
import { access, appendFile } from "node:fs/promises"
import { setTimeout as delay } from "node:timers/promises"

// Public test tool: records actual execution, never decides model responses.
export const ActionProbe: Plugin = async (_, options = {}) => {
  const log = options.log
  if (typeof log !== "string") throw new Error("Action probe requires a log path")
  return { tool: { probe_step: tool({
    description: "Record the requested action in the task artifact. Perform exactly the requested action.",
    args: { action: tool.schema.string() },
    async execute(args, context) {
      const event = { sessionID: context.sessionID, assistantID: context.messageID, action: args.action }
      await appendFile(log, JSON.stringify({ ...event, kind: "started" }) + "\n")
      if (args.action === options.holdAction && typeof options.releaseFile === "string") {
        const end = Date.now() + 30000
        while (Date.now() < end) {
          if (context.abort.aborted) throw new Error("aborted")
          if (await access(options.releaseFile).then(() => true, () => false)) break
          await delay(20)
        }
      }
      await appendFile(log, JSON.stringify({ ...event, kind: "completed" }) + "\n")
      return "Recorded action: " + args.action
    },
  }) } }
}
macos-test-package.yml
name: macOS test package
on:
  workflow_dispatch:
  push:
    branches: [dev]
  pull_request:
    branches: [dev]
permissions:
  contents: read
jobs:
  build:
    strategy:
      fail-fast: false
      matrix:
        include:
          - runner: macos-15
            arch: arm64
          - runner: macos-15-intel
            arch: x64
    runs-on: ${{ matrix.runner }}
    timeout-minutes: 45
    steps:
      - uses: actions/checkout@v4
        with:
          submodules: true
      - uses: actions/setup-node@v4
        with:
          node-version: '24'
      - uses: oven-sh/setup-bun@v2
        with:
          bun-version: '1.4.2'
      - run: node -e 'if (process.platform !== "darwin" || process.arch !== "${{ matrix.arch }}") process.exit(1)'
      - run: bun install --frozen-lockfile
      - run: npm run typecheck
      - run: npm test
      - run: npm run package:test
      - run: node scripts/smoke-test-package.mjs dist/codeagent-opencode-darwin-${{ matrix.arch }}
      # tar preserves executable bits and hidden plugin configuration through ZIP artifacts.
      - run: tar -czf dist/codeagent-opencode-darwin-${{ matrix.arch }}.tar.gz -C dist codeagent-opencode-darwin-${{ matrix.arch }}
      - uses: actions/upload-artifact@v4
        with:
          name: codeagent-opencode-darwin-${{ matrix.arch }}-${{ github.sha }}
          path: dist/codeagent-opencode-darwin-${{ matrix.arch }}.tar.gz
          if-no-files-found: error
          retention-days: 30

